var n=`0530-sholeh-zard`;var t=`world-0530`;var r=`IR`;var a=`western-asia`;var o=8;var s=151;var d={en:`Sholeh Zard`,ua:`Шоле зард`};var g={en:`A traditional dish from Iran, centered on white rice, pistachio. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Іран. Основні складники: білий рис, фісташка. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Cook the listed ingredients in simmering water for about 45 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 45 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:45,i:[[`white-rice`,200,`g`],[`water`,1100,`ml`],[`saffron-threads`,.5,`g`],[`white-granulated-sugar`,220,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`rose-water`,45,`ml`],[`ground-cardamom`,4,`g`],[`unsalted-butter`,35,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 95 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 95 хвилин.`,t:[`rapid-chilling`],m:95,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-cinnamon`,4,`g`],[`pistachio`,40,`g`]]}];var h={slug:n,id:t,country:`IR`,region:a,servings:8,minutes:151,title:d,text:g,steps:l};export{r as country,h as default,t as id,s as minutes,a as region,o as servings,n as slug,l as steps,g as text,d as title};